@namespace sv_347724c508514306a95c35cd40a0b1f0.Components.Pages.Settings
@using sv_347724c508514306a95c35cd40a0b1f0.Services

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme Selector -->
    <div class="form-group">
        <label class="group-label">Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-label">
                    <input type="radio" name="theme" value="@theme"
                           checked="@(Theme == theme)"
                           @onchange="() => Theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size Selector -->
    <div class="form-group">
        <label class="group-label">Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-label">
                    <input type="radio" name="fontSize" value="@size"
                           checked="@(FontSize == size)"
                           @onchange="() => FontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language Dropdown -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language" class="form-control">
            @foreach (var lang in Languages)
            {
                <option value="@lang">@lang</option>
            }
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="toggle-group">
        <label class="toggle-label">
            <input type="checkbox" @bind="CompactMode" />
            <span>Compact Mode</span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p class="preview-text">This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>Here is some example content displayed with your chosen theme and font size.</p>
            <button class="preview-btn">Sample Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    private static readonly string[] Languages = { "English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese" };

    private bool _initialized;

    protected override void OnParametersSet()
    {
        if (Settings is not null && !_initialized)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
            _initialized = true;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"theme-{Theme.ToLowerInvariant()} font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
    }
}

